<?php
declare(strict_types=1);
namespace Morshed\Product;
use Morshed\Core\{Database,Audit,Security,Problem};
final class Behavior
{
 public function __construct(private Database $db){}
 public function record(string $uid,?string $bid,string $event,string $actor,string $note='',string $status='confirmed',string $evidence=''):string {
  $id=Security::id();$dedup=$bid&&$event!=='appeal'?hash('sha256',$bid.'|'.$uid.'|'.$event):null;$insert=$this->db->run('INSERT IGNORE INTO m_behavior_events(id,user_id,booking_id,event,status,actor_id,note,evidence,review_note,dedup_key,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$id,$uid,$bid,$event,$status,$actor,$note,$evidence,'',$dedup,time()]);if(!$insert->rowCount()&&$dedup)return $this->db->one('SELECT id FROM m_behavior_events WHERE dedup_key=?',[$dedup])['id'];return $id;
 }
 public function report(array $a,array $d):string {return (new Membership($this->db))->write(function()use($a,$d){$b=(new Consultations($this->db,new Audit($this->db)))->booking($a,Policy::text($d['booking_id']??'',32));$event=Policy::choice($d['event']??'',['no_show','late','technical','misconduct']);if((int)$b['starts_at']>time())throw new Problem('INVALID_STATE','پیش از زمان جلسه گزارش حضور ثبت نمی‌شود.',409);if(in_array($event,['no_show','late'],true)&&($b['state']!=='confirmed'||($event==='no_show'&&(int)$b['ends_at']>time())))throw new Problem('INVALID_STATE','گزارش غیبت یا تأخیر فقط برای جلسهٔ قطعی و غیبت پس از پایان زمان آن قابل ثبت است.',409);$target=Policy::text($d['user_id']??'',32);if(!in_array($target,[$b['user_id'],$b['mentor_id']],true))throw new Problem('INVALID_INPUT','طرف جلسه را انتخاب کنید.');$note=Policy::text($d['note']??'',4000,10);$evidence=Policy::text($d['evidence']??'',4000,0);$id=$this->record($target,$b['id'],$event,$a['user_id'],$note,'reported',$evidence);(new Audit($this->db))->add($a['user_id'],'site','behavior.reported',$b['id']);return $id;});}
 public function review(array $a,array $d):void {$m=new Membership($this->db);$m->central($a);$m->write(function()use($a,$d,$m){$id=Policy::text($d['id']??'',32);$r=$this->db->one('SELECT * FROM m_behavior_events WHERE id=? FOR UPDATE',[$id]);if(!$r||$r['status']!=='reported')throw new Problem('INVALID_STATE','این گزارش بررسی شده یا پیدا نشد.',409);if(in_array($a['user_id'],[$r['user_id'],$r['actor_id']],true))throw new Problem('SEPARATION_REQUIRED','رسیدگی باید توسط مدیر مستقل انجام شود.',403);$status=Policy::choice($d['status']??'',['confirmed','dismissed']);$note=Policy::text($d['review_note']??'',4000,5);$this->db->run('UPDATE m_behavior_events SET status=?,reviewed_by=?,reviewed_at=?,review_note=? WHERE id=?',[$status,$a['user_id'],time(),$note,$id]);
  if($status==='confirmed'&&$r['event']==='appeal'&&$r['appeal_of']){$this->db->run('UPDATE m_service_restrictions SET revoked_by=?,revoked_at=? WHERE event_id=? AND revoked_at IS NULL',[$a['user_id'],time(),$r['appeal_of']]);$this->db->run("UPDATE m_behavior_events SET status='dismissed',reviewed_by=?,review_note=?,reviewed_at=? WHERE id=?",[$a['user_id'],$note,time(),$r['appeal_of']]);}
  if($status==='confirmed'&&$r['event']==='no_show'){
   $p=$m->policy();$count=(int)$this->db->run("SELECT COUNT(*) FROM m_behavior_events WHERE user_id=? AND event='no_show' AND status='confirmed' AND created_at>=?",[$r['user_id'],time()-(int)$p['behavior_days']*86400])->fetchColumn();$days=$count>=3?(int)$p['third_days']:($count>=2?(int)$p['second_days']:0);if($days)$this->restrict($a,$r['user_id'],$days,$note,$id);
   if($r['booking_id']){$b=$this->db->one('SELECT * FROM m_bookings WHERE id=?',[$r['booking_id']]);if($b&&$b['state']==='confirmed'){(new ConsultationCredits($this->db))->settle($b,$b['user_id']===$r['user_id']?'user_no_show':'mentor_no_show',$a['user_id'],$note);$this->db->run("UPDATE m_bookings SET state='cancelled' WHERE id=?",[$b['id']]);$this->db->run("INSERT INTO m_booking_events(booking_id,actor_id,event,note,created_at) VALUES(?,?,'no_show_confirmed',?,?)",[$b['id'],$a['user_id'],$note,time()]);}}
  }
  $au=new Audit($this->db);$au->add($a['user_id'],'admin','behavior.'.$status,$id);$au->notify($r['user_id'],'نتیجهٔ بررسی گزارش رفتاری',$note.'؛ امکان ثبت اعتراض در حساب شما وجود دارد.','/account');
 });}
 private function restrict(array $a,string $uid,int $days,string $reason,?string $event):void {$this->db->run('INSERT INTO m_service_restrictions(id,user_id,event_id,reason,starts_at,ends_at,created_by) VALUES(?,?,?,?,?,?,?)',[Security::id(),$uid,$event,$reason,time(),time()+$days*86400,$a['user_id']]);(new Audit($this->db))->notify($uid,'محدودیت خدمات مشاوره',$reason.' — به مدت '.$days.' روز؛ مطالعهٔ تجربه‌ها در دسترس است.','/account');}
 public function restriction(array $a,array $d):void {$m=new Membership($this->db);$m->central($a);$m->write(function()use($a,$d){if(!empty($d['revoke_id'])){$id=Policy::text($d['revoke_id'],32);$r=$this->db->one('SELECT user_id FROM m_service_restrictions WHERE id=? AND revoked_at IS NULL FOR UPDATE',[$id]);if(!$r)throw new Problem('NOT_FOUND','محدودیت فعال پیدا نشد.',404);$note=Policy::text($d['reason']??'',4000,5);$this->db->run('UPDATE m_service_restrictions SET revoked_by=?,revoked_at=? WHERE id=?',[$a['user_id'],time(),$id]);(new Audit($this->db))->notify($r['user_id'],'محدودیت مشاوره رفع شد',$note,'/account');}else{$uid=Policy::text($d['user_id']??'',32);if(!$this->db->one("SELECT id FROM m_users WHERE id=? AND status='active'",[$uid]))throw new Problem('NOT_FOUND','کاربر پیدا نشد.',404);$this->restrict($a,$uid,Policy::integer($d['days']??'',1,365),Policy::text($d['reason']??'',4000,5),null);}(new Audit($this->db))->add($a['user_id'],'admin','behavior.restriction_changed');});}
 public function appeal(array $a,array $d):string {(new Policy($this->db))->user($a);return (new Membership($this->db))->write(function()use($a,$d){$id=Policy::text($d['id']??'',32);$event=$this->db->one("SELECT * FROM m_behavior_events WHERE id=? AND user_id=? AND status='confirmed' AND event IN ('no_show','late','misconduct')",[$id,$a['user_id']]);if(!$event)throw new Problem('NOT_FOUND','سابقهٔ قابل اعتراض پیدا نشد.',404);if($this->db->one('SELECT id FROM m_behavior_events WHERE appeal_of=?',[$id]))throw new Problem('CONFLICT','اعتراض قبلاً ثبت شده است.',409);$note=Policy::text($d['note']??'',4000,15);$appeal=$this->record($a['user_id'],$event['booking_id'],'appeal',$a['user_id'],$note,'reported');$this->db->run('UPDATE m_behavior_events SET appeal_of=? WHERE id=?',[$id,$appeal]);(new Audit($this->db))->add($a['user_id'],'site','behavior.appealed',$id);return $appeal;});}
}
